  "insp.lotRights": "Rights of this lot (DTC)",
  "insp.resourceRights": "Rights of this resource (DTC)",
  "insp.lotRightsHint": "Applies to ALL the files of the lot: each one reads this licence up the chain, and one that has its own wins (the more specific sentence is the one said about that object). Empty = not declared.",
  "insp.resourceRightsHint": "Applies to the BYTES: while the embargo runs the server serves the file only to whoever works on the study (editor and up), and the licence travels with the download. Empty = not declared (then the graph's default applies).",
  "insp.licence": "Licence",
  "insp.applyDefaultLicence": "Apply CC-BY-SA-4.0",
  "insp.applyDefaultLicenceTitle": "The StratiGraph default. Until you apply it the licence stays NOT declared: the server exposes it as a default, which is a different thing from a licence granted.",
  // ── HDT-O · the attribution, and the three states it can be in ────────────
  //
  // The words a director of excavations reads. The CODES (HC9, HC1, HC2, HC13)
  // are in the glossary tooltips, never on a label: they are what the ontology
  // and the papers use, and they say nothing to the person filling the form.
  //
  // And the one sentence that matters: NOT KNOWING YET IS NORMAL. The old hint
  // called the twin «optional» — the thing that gives a site its identity,
  // described as a checkbox — and said nothing about what it is for.
  "insp.hdt": "Which monument this study is about",
  "insp.hdtHint":
    "Naming the monument, site or landscape is what makes eight campaigns ONE place instead of eight unrelated documents — and what lets other people find your work next to theirs. Not knowing yet is normal: leave it, keep digging, and say it later.",
  "insp.hdtStudy": "This study",
  "insp.hdtStudyGloss": "HC9 · Study — the campaign, the season, the piece of work this graph records.",
  "insp.hdtStudyTitle": "Title",
  "insp.hdtStudyTitlePh": "e.g. Aiano, 2026 campaign",
  "insp.hdtStudyAuthors": "Author(s)",
  "insp.hdtStudyAuthorsPh": "e.g. Rossi, Bianchi",
  "insp.hdtStudyDate": "Date",
  "insp.hdtStudyDatePh": "e.g. 2026",
  "insp.hdtEntity": "The thing in the world",
  "insp.hdtEntityGloss": "HC1 · Heritage entity — the monument, site or landscape itself, as opposed to any digital record of it.",
  "insp.hdtEntityName": "Name",
  "insp.hdtEntityNamePh": "e.g. Villa di Aiano",
  "insp.hdtParent": "Part of",
  "insp.hdtParentPh": "the whole it belongs to, e.g. Poggibonsi",
  "insp.hdtTwin": "Its digital twin",
  "insp.hdtTwinGloss": "HC2 · Heritage Digital Twin — the shared digital record of that thing, which several studies can hang on.",
  "insp.hdtProject": "The project",
  "insp.hdtProjectGloss": "HC13 · Project — the funded or institutional frame the study was made in.",
  "insp.hdtProjectName": "Name",
  "insp.hdtProjectNamePh": "optional",
  "insp.hdtProjectHint":
    "Free text, and deliberately so: the authority files behind the fields above answer «where», «when», «what kind» and «who», and a research project is none of those. Hanging it on the nearest one would make it LOOK resolved. A project register (CORDIS, ROR, a grant DOI) needs a facet of its own first.",
  // the authority sub-field, shared by the entity and its whole
  "insp.authority": "Authority",
  "insp.authorityPlaceholder": "type to search an authority, or paste a URI",
  "insp.authorityOffline": "Offline resolver: type a term, pick a match, or paste a URI.",
  "insp.authorityNoResolver": "Paste an authority URI (resolver unavailable).",
  "insp.authorityUnresolved": "Free text — not resolved against an authority.",
  // the three states
  "insp.twinStateNone": "Not attributed yet",
  "insp.twinStateNoneHint":
    "You are digging and do not yet know what this belongs to. That is a state, not a blank: nothing below has to be filled in for the rest of the study to work.",
  "insp.twinStateProvisional": "Provisional twin",
  "insp.twinStateProvisionalHint":
    "One you made yourself, so you had somewhere to put what you are finding — an ordinary thing to do. It lives in this document only; at publication it can be declared new, or recognised as somebody else's.",
  "insp.twinStateRegistered": "Registered twin",
  "insp.twinStateRegisteredHint":
    "Known by a register ({registry}), so other people find it and their campaigns can be read beside yours.",
  "insp.twinName": "Name of the twin",
  "insp.twinNamePh": "e.g. Villa di Aiano HDT",
  "insp.twinKey": "Shared identity",
  "insp.twinDetach": "This is not the one",
  "insp.twinDetachTitle": "Detaches the twin from this study. Nothing else is deleted — the study, the entity and the graph stay exactly as they are.",
  "insp.twinNeedsEntity":
    "Give the thing a name first, however roughly — a twin is a twin OF something, so «an unnamed building under the north field» is enough to start one.",
  "insp.twinCreate": "Create a provisional twin",
  "insp.twinCreateTitle": "Somewhere of your own to put what you are finding. It can be published later, and merged with an existing twin if it turns out to be the same thing.",
  "insp.twinFallbackName": "Heritage",
  "insp.twinSearch": "Is there one already?",
  "insp.twinSearchPh": "monument name, or paste an identifier",
  "insp.twinLook": "Look",
  "insp.twinSearching": "asking the register…",
  "insp.twinSearchHint":
    "A suggestion, never an obligation: you can create your own, or leave it for later.",
  "insp.twinNoRegister":
    "No register answered — that is not the same as «there is none». You can still create a provisional twin.",
