  "assets.needsIdentity": "Il tab Asset vuole un'identità: l'attribuzione è un ATTO e qualcuno lo firma. Dichiara il tuo ORCID in Impostazioni ▸ Identità — funziona offline — e torna qui.",
  "assets.needsDocument": "Nessun documento aperto: un file pubblicato senza un grafo in cui metterlo sarebbero byte in un secchio. Apri o crea un grafo.",
  "assets.drop": "Lascia qui i file — o trascinali dal riquadro del disco — e vanno subito in «{room}», ognuno con la consegna qui sopra. Un trascinamento è un LOTTO: arrivano insieme, come una sola acquisizione, e tutto resta raffinabile dopo.",
