  "assets.queued": "{n} in coda",
  "assets.fromShelf": "Prendi i {n} dallo scaffale",
  "assets.fromShelfHint": "Lo scaffale contiene già i file che hai scelto dal disco, col checksum calcolato dal bridge. Una sola superficie Storage è montata alla volta, quindi trascinare dal riquadro di sinistra a questo non è ancora un gesto che esiste: questa è la via d'ingresso per un file su disco.",
  "assets.lot": "Nome del lotto",
  "assets.lotPlaceholder": "Volo 2026-03, foto Saggio II…",
  "assets.lotHint": "Conviene scriverlo. Un lotto senza nome è comunque UN lotto — questa consegna si fa il suo id — ma il corpus lo etichetta appena atterra il primo file, quindi un lotto di trecento foto finisce per leggersi «Acquisition of 1 file(s)». Un nome lo sostituisce, e trascinando altri file con lo stesso nome si aggiungono a quello.",
  "assets.license": "Licenza",
  "assets.licenseHint": "Detta una volta, per tutto il lotto. Ogni file la legge risalendo la catena — non viene copiata su ognuno, perché una copia è una cosa che può discordare.",
  "assets.author": "Autore (chi l'ha fatto)",
  "assets.authorPlaceholder": "nome e cognome",
  "assets.authorHint": "Chi ha prodotto questi byte — anche una persona che non è qui. L'attributore sei TU, e resta scritto a parte: l'atto è firmato col tuo iD.",
  "assets.orcidBad": "ORCID non valido ({problem}) — non l'ho scritto.",
  "assets.residencyLabel": "Dove stanno i byte",
  "assets.residency.resident": "resident (nello store della stanza)",
